# Seed a compound scenario on a fresh zone (country US, zone 70): base GST 5% (priority 1, non-piggyback)
# + QST 8% (priority 2, piggyback). base 100 -> GST 5.00 (running 105), QST 8% of 105 = 8.40.
assert_status_and_capture 64 "Seed GST base rate (5%, priority 1) on zone 70" "BR-TAX-020" \
    "POST" "$API_URL/tax-rates" \
    "{\"code\":\"GSTB$UNIQ\",\"rate_text\":\"5.0000\",\"tax_class_id\":\"$CALC_CLASS_ID\",\"country_iso_code\":\"US\",\"zone_id\":70,\"piggyback\":false,\"tax_priority\":1,\"descriptions\":[{\"language_id\":1,\"name\":\"GST\"}]}" \
    "201"
GSTB_RATE_ID=$(extract_field "$LAST_BODY" "id")

assert_status_and_capture 65 "Seed QST piggyback rate (8%, priority 2) on zone 70" "BR-TAX-021" \
    "POST" "$API_URL/tax-rates" \
    "{\"code\":\"QST$UNIQ\",\"rate_text\":\"8.0000\",\"tax_class_id\":\"$CALC_CLASS_ID\",\"country_iso_code\":\"US\",\"zone_id\":70,\"piggyback\":true,\"tax_priority\":2,\"parent_id\":\"$GSTB_RATE_ID\",\"descriptions\":[{\"language_id\":1,\"name\":\"QST\"}]}" \
    "201"

# BR-TAX-020: each rate applies its percentage to the class taxable base (GST 5% of 100 = 5.00).
assert_json_field 66 "Base rate applies percentage to taxable base (GST amount 5.00)" "BR-TAX-020" \
    "POST" "$API_URL/calculate" \
    '{"customer":{"billing":{"country_id":840,"zone_id":70}},"items":[{"unit_price":100.00,"quantity":1,"tax_class_code":null}],"language_id":1}' \
    '"amount":5.0'

# BR-TAX-021: piggyback stacks on the running taxed total (QST 8% of 105.00 = 8.40).
assert_json_field 67 "Piggyback compounds on running total (QST amount 8.40)" "BR-TAX-021" \
    "POST" "$API_URL/calculate" \
    '{"customer":{"billing":{"country_id":840,"zone_id":70}},"items":[{"unit_price":100.00,"quantity":1,"tax_class_code":null}],"language_id":1}' \
    '"amount":8.4'

# BR-TAX-022: each emitted line rounded to 2dp half-up. 19.99 * 7.25% = 1.449275 -> 1.45.
# Reuse the state-based CA rate (7.25%) via state path.
assert_json_field 68 "Per-line rounding half-up to 2dp (1.449275 -> 1.45)" "BR-TAX-022" \
    "POST" "$API_URL/calculate" \
    '{"customer":{"billing":{"country_id":840,"zone_id":null,"state":"California"}},"items":[{"unit_price":19.99,"quantity":1,"tax_class_code":null}]}' \
    '"amount":1.45'

# BR-TAX-020: tax line carries a label (rate description name in requested language).
assert_json_field 69 "Tax line carries label from rate description" "BR-TAX-020" \
    "POST" "$API_URL/calculate" \
    '{"customer":{"billing":{"country_id":840,"zone_id":70}},"items":[{"unit_price":100.00,"quantity":1,"tax_class_code":null}],"language_id":1}' \
    '"label"'

# BR-TAX-023 [D-06 PRESERVED-AS-IS]: duplicate-code lines are deduped to the FIRST (not summed).
